'use strict';
// file:// からでも再生できる同梱音声。サーバーへの取得要求は行いません。
const BundledAudio=(()=>{
 const goal='';
 const crowd='';
 const praise='';
 const save='';
 function blob(value,type){return new Blob([Uint8Array.from(atob(value),c=>c.charCodeAt(0))],{type});}
 return {goalBlob:()=>blob(goal,'audio/mpeg'),crowdBlob:()=>blob(crowd,'audio/wav'),praiseBlob:()=>blob(praise,'audio/mpeg'),saveBlob:()=>blob(save,'audio/mpeg')};
})();
